values ('learning-tutor-v2','learning-room-v1','0736124795fd1dbc5e5b82521f919162ea82692c27a3f127b850410ce31f6054','495079bb614ff51269ae2d183360efe2deb48e0da1ac2ac9a0bc9a76034035ae','{"schemaVersion":1,"manifestVersion":"learning-tutor-v2","contentVersion":"learning-room-v1","contentHash":"0736124795fd1dbc5e5b82521f919162ea82692c27a3f127b850410ce31f6054","topicMap":[{"topicCode":"materials","activityCode":"beginner-materials","resourceCode":"materials-and-components","sourceRefs":["vic-sorting","arl"],"title":{"en":"Identify the material","zh":"辨认材料"},"templateCode":"tutor-materials-v1"},{"topicCode":"sorting","activityCode":"beginner-bin-action","resourceCode":"local-sorting-guide","sourceRefs":["vic-sorting","vic-fogo"],"title":{"en":"Check collection conditions","zh":"核对收集条件"},"templateCode":"tutor-sorting-v1"},{"topicCode":"causes","activityCode":"beginner-why-waste","resourceCode":"plan-before-shopping","sourceRefs":["vic-planning"],"title":{"en":"Notice avoidable waste","zh":"发现可避免的浪费"},"templateCode":"tutor-causes-v1"},{"topicCode":"climate-basics","activityCode":"advanced-climate","resourceCode":"waste-climate-sdg13","sourceRefs":["unfccc-2024","sdg13"],"title":{"en":"Connect waste and climate","zh":"联系浪费与气候"},"templateCode":"tutor-climate-basics-v1"},{"topicCode":"components","activityCode":"intermediate-components","resourceCode":"materials-and-components","sourceRefs":["arl"],"title":{"en":"Read each part","zh":"逐个阅读部件"},"templateCode":"tutor-components-v1"},{"topicCode":"clean-streams","activityCode":"intermediate-clean-streams","resourceCode":"local-sorting-guide","sourceRefs":["vic-sorting"],"title":{"en":"Prepare accepted recycling","zh":"准备可接收回收物"},"templateCode":"tutor-clean-streams-v1"},{"topicCode":"local-collection","activityCode":"intermediate-local-guide","resourceCode":"local-sorting-guide","sourceRefs":["vic-sorting","vic-glass"],"title":{"en":"Ask about the local route","zh":"询问当地方式"},"templateCode":"tutor-local-collection-v1"},{"topicCode":"reuse-resources","activityCode":"intermediate-components","resourceCode":"materials-and-components","sourceRefs":["vic-reuse","vic-single-use"],"title":{"en":"Reuse suitable items","zh":"再利用合适物品"},"templateCode":"tutor-reuse-resources-v1"},{"topicCode":"planning","activityCode":"advanced-plan-first","resourceCode":"plan-before-shopping","sourceRefs":["vic-planning"],"title":{"en":"Plan with available food","zh":"用已有食物规划"},"templateCode":"tutor-planning-v1"},{"topicCode":"storage-safety","activityCode":"advanced-storage","resourceCode":"date-labels-and-storage","sourceRefs":["fsanz-dates","fsanz-safety"],"title":{"en":"Put safety first","zh":"安全优先"},"templateCode":"tutor-storage-safety-v1"},{"topicCode":"prevention-priority","activityCode":"advanced-plan-first","resourceCode":"plan-before-shopping","sourceRefs":["vic-planning","vic-fogo"],"title":{"en":"Prevent surplus first","zh":"先预防多余食物"},"templateCode":"tutor-prevention-priority-v1"},{"topicCode":"climate-evidence","activityCode":"advanced-climate","resourceCode":"waste-climate-sdg13","sourceRefs":["unep-index-2024","sdg13"],"title":{"en":"Read dates and scope","zh":"阅读年份与范围"},"templateCode":"tutor-climate-evidence-v1"}],"knowledge":[{"chunkCode":"beginner-why-waste:0","entityCode":"beginner-why-waste","title":{"en":"Why food gets wasted","zh":"食物为什么被浪费"},"topicCodes":["causes"],"sourceRefs":["ozharvest-2025"],"block":{"type":"paragraph","text":{"en":"Watch the one-minute story, or read this summary. Food can slip out of sight while shopping and meal plans move on. Checking what is already at home creates a useful pause before buying more.","zh":"观看一分钟故事，或阅读这份摘要。购物和餐食安排不断变化，食物却可能被遗忘。多买之前先查看家里已有的食物，是一个有用的停顿。"}}},{"chunkCode":"beginner-why-waste:1","entityCode":"beginner-why-waste","title":{"en":"Why food gets wasted","zh":"食物为什么被浪费"},"topicCodes":["causes"],"sourceRefs":["ozharvest-2025"],"block":{"type":"paragraph","text":{"en":"OzHarvest''s 2025 research describes Australian households with someone under 35 discarding about 113 kg of food a year, valued at over A$1,500. This is a survey estimate for that group, not a measurement of you.","zh":"OzHarvest 2025 年研究估计，有 35 岁以下成员的澳大利亚家庭每年丢弃约 113 kg 食物，价值超过 A$1,500。这是该群体的调查估计，不是对你的测量。"}}},{"chunkCode":"beginner-why-waste:2","entityCode":"beginner-why-waste","title":{"en":"Why food gets wasted","zh":"食物为什么被浪费"},"topicCodes":["causes"],"sourceRefs":["ozharvest-2025"],"block":{"type":"reflection","title":{"en":"Try it in your kitchen","zh":"在你的厨房试一试"},"text":{"en":"Name one ingredient you already have that could be part of your next meal.","zh":"找出一种家里已有、可以用于下一餐的食材。"}}},{"chunkCode":"beginner-materials:0","entityCode":"beginner-materials","title":{"en":"Know your materials","zh":"认识材料"},"topicCodes":["materials"],"sourceRefs":["vic-sorting","arl"],"block":{"type":"paragraph","text":{"en":"Start with what the item actually is. Food scraps, metal, paper, glass and plastics have different roles. A package can contain several of them. A silver-looking object or an illustration alone does not prove a material.","zh":"先确认物品本身是什么。食物残余、金属、纸、玻璃和塑料是不同类别；一件包装可能包含多种材料。银色外观或插图本身不能证明材质。"}}},{"chunkCode":"beginner-materials:1","entityCode":"beginner-materials","title":{"en":"Know your materials","zh":"认识材料"},"topicCodes":["materials"],"sourceRefs":["vic-sorting","arl"],"block":{"type":"bullet-list","items":[{"en":"Confirmed aluminium → metal.","zh":"已确认的铝 → 金属。"},{"en":"Plain cardboard → paper-based material.","zh":"普通纸板 → 纸类材料。"},{"en":"Fruit peel → food residue.","zh":"果皮 → 食物残余。"},{"en":"Scrunchable plastic film → soft plastic, not a rigid container.","zh":"可揉团的塑料薄膜 → 软塑料，不是硬容器。"}]}},{"chunkCode":"beginner-materials:2","entityCode":"beginner-materials","title":{"en":"Know your materials","zh":"认识材料"},"topicCodes":["materials"],"sourceRefs":["vic-sorting","arl"],"block":{"type":"paragraph","text":{"en":"Now check the route. Read instructions for each packaging part and the local service. A recycling triangle or plastic code does not by itself confirm that your council accepts the item. When uncertain, look it up instead of adding it to recycling.","zh":"再核对处理方式。查看各包装部件说明与当地服务。回收三角符号或塑料编号本身并不保证当地 council 接受该物品。不确定时先查，不直接塞进回收。"}}},{"chunkCode":"beginner-materials:3","entityCode":"beginner-materials","title":{"en":"Know your materials","zh":"认识材料"},"topicCodes":["materials"],"sourceRefs":["vic-sorting","arl"],"block":{"type":"paragraph","text":{"en":"Example: a snack has a cardboard sleeve and a soft-plastic wrapper. Identify both parts; do not let the sleeve''s recycling instruction stand in for the wrapper''s.","zh":"例子：零食有纸板套和软塑料膜。应分别辨认，不能把纸板套的回收说明套用到薄膜上。"}}},{"chunkCode":"beginner-materials:4","entityCode":"beginner-materials","title":{"en":"Know your materials","zh":"认识材料"},"topicCodes":["materials"],"sourceRefs":["vic-sorting","arl"],"block":{"type":"reflection","title":{"en":"Try it in your kitchen","zh":"在你的厨房试一试"},"text":{"en":"Choose one package at home. Find its parts, material clues and collection instructions. If something is missing, note what you need to check.","zh":"选一件家里的包装，找出部件、材质线索和收集说明。若信息不足，记下需要核对的内容。"}}},{"chunkCode":"beginner-bin-action:0","entityCode":"beginner-bin-action","title":{"en":"Practise with Bin Action","zh":"分类练习"},"topicCodes":["sorting"],"sourceRefs":["vic-sorting","vic-fogo"],"block":{"type":"paragraph","text":{"en":"Practise with an empty aluminium can, a banana peel and a clean cardboard box. Each question states what the example service accepts. Choose by tapping a bin, or use the drag interaction when available.","zh":"练习空铝罐、香蕉皮和干净纸箱。每题会说明示例服务接受什么。可以点选桶，或在可用时拖拽物品。"}}},{"chunkCode":"beginner-bin-action:1","entityCode":"beginner-bin-action","title":{"en":"Practise with Bin Action","zh":"分类练习"},"topicCodes":["sorting"],"sourceRefs":["vic-sorting","vic-fogo"],"block":{"type":"paragraph","text":{"en":"Read the explanation after each first answer. A demonstration retry helps you learn, but does not replace the recorded first answer. Finish all three feedback steps to complete this activity.","zh":"首次作答后阅读解释。再次演示有助于学习，但不会改写首次答案。确认三题反馈后完成此活动。"}}},{"chunkCode":"beginner-bin-action:2","entityCode":"beginner-bin-action","title":{"en":"Practise with Bin Action","zh":"分类练习"},"topicCodes":["sorting"],"sourceRefs":["vic-sorting","vic-fogo"],"block":{"type":"paragraph","text":{"en":"This practice uses teaching items. It does not consume fridge stock or count as a real disposal. Your Beginner checkpoint remains a separate six-question assessment.","zh":"练习使用教学物品，不消耗冰箱库存，也不算真实投放。初级 checkpoint 是另外的六题测验。"}}},{"chunkCode":"beginner-bin-action:3","entityCode":"beginner-bin-action","title":{"en":"Practise with Bin Action","zh":"分类练习"},"topicCodes":["sorting"],"sourceRefs":["vic-sorting","vic-fogo"],"block":{"type":"reflection","title":{"en":"Try it in your kitchen","zh":"在你的厨房试一试"},"text":{"en":"What detail in the collection instructions changed your decision?","zh":"收集说明中的哪个细节影响了你的选择？"}}},{"chunkCode":"intermediate-components:0","entityCode":"intermediate-components","title":{"en":"One item, several materials","zh":"一件物品，多种材料"},"topicCodes":["components","reuse-resources"],"sourceRefs":["arl","vic-sorting","vic-reuse","vic-glass"],"block":{"type":"paragraph","text":{"en":"One product does not always mean one disposal instruction. A box, inner wrap and lid may have different instructions. Find the name of each part, then read the instruction attached to that part.","zh":"一个产品不一定只有一种处理说明。盒、内膜和盖子可能各有要求。先找到部件名称，再阅读属于该部件的说明。"}}},{"chunkCode":"intermediate-components:1","entityCode":"intermediate-components","title":{"en":"One item, several materials","zh":"一件物品，多种材料"},"topicCodes":["components","reuse-resources"],"sourceRefs":["arl","vic-sorting","vic-reuse","vic-glass"],"block":{"type":"paragraph","text":{"en":"The Australasian Recycling Label distinguishes recyclable, conditionally recyclable and not recyclable components. A condition may require preparation or a collection route. Do not skip it or apply one part''s symbol to everything.","zh":"Australasian Recycling Label 区分可回收、有条件可回收和不可回收部件。条件可能要求准备步骤或特定收集方式，不能跳过，也不能把一个部件的标识当作全部包装的说明。"}}},{"chunkCode":"intermediate-components:2","entityCode":"intermediate-components","title":{"en":"One item, several materials","zh":"一件物品，多种材料"},"topicCodes":["components","reuse-resources"],"sourceRefs":["arl","vic-sorting","vic-reuse","vic-glass"],"block":{"type":"paragraph","text":{"en":"Example: after safely using the food in a tub, separate any residue from the packaging. Check the tub and lid instructions. For glass jar lids, the council''s rules can differ; do not assume every lid stays on or off.","zh":"例子：安全使用盒中食物后，将残余与包装分开，查看盒身与盖子的说明。玻璃罐盖的 council 规则可能不同，不要认为所有盖子都应保留或取下。"}}},{"chunkCode":"intermediate-components:3","entityCode":"intermediate-components","title":{"en":"One item, several materials","zh":"一件物品，多种材料"},"topicCodes":["components","reuse-resources"],"sourceRefs":["arl","vic-sorting","vic-reuse","vic-glass"],"block":{"type":"reflection","title":{"en":"Try it in your kitchen","zh":"在你的厨房试一试"},"text":{"en":"Read a multi-part package. Can you name the instruction for every part? Only separate parts in the way the instructions require.","zh":"阅读一个多部件包装。你能说出每个部件的要求吗？只按说明要求分离。"}}},{"chunkCode":"intermediate-clean-streams:0","entityCode":"intermediate-clean-streams","title":{"en":"Keep recycling useful","zh":"避免回收污染"},"topicCodes":["clean-streams"],"sourceRefs":["vic-sorting","vic-fogo","vic-glass"],"block":{"type":"paragraph","text":{"en":"A collection stream works best when it contains the items the service expects. Extra food, plastic bags or the wrong material can make recovery harder. Preparation follows the receiving service, not a universal ritual.","zh":"收集流中最好只包含该服务预期接收的物品。多余食物、塑料袋或错误材料可能妨碍回收。准备方式以接收服务为准，并非处处一样。"}}},{"chunkCode":"intermediate-clean-streams:1","entityCode":"intermediate-clean-streams","title":{"en":"Keep recycling useful","zh":"避免回收污染"},"topicCodes":["clean-streams"],"sourceRefs":["vic-sorting","vic-fogo","vic-glass"],"block":{"type":"bullet-list","items":[{"en":"Empty accepted containers; rinse if needed.","zh":"倒空可接受的容器，必要时冲洗。"},{"en":"Keep mixed-recycling items loose where the service requires it.","zh":"服务要求散放时，不将混合回收物装袋。"},{"en":"Keep paper/cardboard clean and dry; tissues are different.","zh":"纸与纸板保持干净、干燥；纸巾需区别处理。"},{"en":"Remove packaging and fruit stickers from FOGO scraps.","zh":"从 FOGO 食物残余中去掉包装和水果贴纸。"}]}},{"chunkCode":"intermediate-clean-streams:2","entityCode":"intermediate-clean-streams","title":{"en":"Keep recycling useful","zh":"避免回收污染"},"topicCodes":["clean-streams"],"sourceRefs":["vic-sorting","vic-fogo","vic-glass"],"block":{"type":"paragraph","text":{"en":"Example: a used yogurt tub and a banana peel are not one waste item. The remaining food needs its accepted organics route; the empty tub needs its own material and collection check.","zh":"例子：用过的酸奶盒与香蕉皮不是同一种废弃物。剩余食物应核对合适的有机物收集方式；空盒需另外核对材质和收集要求。"}}},{"chunkCode":"intermediate-clean-streams:3","entityCode":"intermediate-clean-streams","title":{"en":"Keep recycling useful","zh":"避免回收污染"},"topicCodes":["clean-streams"],"sourceRefs":["vic-sorting","vic-fogo","vic-glass"],"block":{"type":"reflection","title":{"en":"Try it in your kitchen","zh":"在你的厨房试一试"},"text":{"en":"Find one preparation step you can make easier with a small kitchen routine.","zh":"找出一个可以通过厨房小习惯更容易完成的准备步骤。"}}},{"chunkCode":"intermediate-local-guide:0","entityCode":"intermediate-local-guide","title":{"en":"Find the right collection","zh":"找到正确收集方式"},"topicCodes":["local-collection"],"sourceRefs":["vic-sorting","vic-glass","cds-vic"],"block":{"type":"paragraph","text":{"en":"Victoria''s guide is a starting point, not proof that your home has every service. Check the council or private waste provider for the address. Service availability, glass separation and lid instructions can differ.","zh":"Victoria 指引是起点，不能证明你的住所拥有所有服务。应按地址查看 council 或私人垃圾服务商。服务是否提供、玻璃是否分收以及盖子要求都可能不同。"}}},{"chunkCode":"intermediate-local-guide:1","entityCode":"intermediate-local-guide","title":{"en":"Find the right collection","zh":"找到正确收集方式"},"topicCodes":["local-collection"],"sourceRefs":["vic-sorting","vic-glass","cds-vic"],"block":{"type":"paragraph","text":{"en":"Soft-plastic collections can change. Confirm a service is active and accepts the exact item before using it. A photograph, an old post or a recycling triangle is not enough.","zh":"软塑料收集安排会变化。使用之前确认服务正在运行，并接受该具体物品。照片、旧帖或回收三角符号都不足以保证。"}}},{"chunkCode":"intermediate-local-guide:2","entityCode":"intermediate-local-guide","title":{"en":"Find the right collection","zh":"找到正确收集方式"},"topicCodes":["local-collection"],"sourceRefs":["vic-sorting","vic-glass","cds-vic"],"block":{"type":"paragraph","text":{"en":"CDS Vic is a separate option for eligible drink containers. Use its official eligibility check and current refund-point finder. Ordinary jars and other containers do not become eligible simply because they are glass or metal.","zh":"CDS Vic 是符合条件饮料容器的另一种选择。应使用官方资格查询与有效退费点地图。普通罐子或其他容器不会仅因为是玻璃或金属就自动符合条件。"}}},{"chunkCode":"intermediate-local-guide:3","entityCode":"intermediate-local-guide","title":{"en":"Find the right collection","zh":"找到正确收集方式"},"topicCodes":["local-collection"],"sourceRefs":["vic-sorting","vic-glass","cds-vic"],"block":{"type":"reflection","title":{"en":"Try it in your kitchen","zh":"在你的厨房试一试"},"text":{"en":"Find the provider serving your home. Write down one item rule you had to look up rather than guess.","zh":"找到服务你住所的提供方，记下一项你需要查而非猜的物品规则。"}}},{"chunkCode":"advanced-plan-first:0","entityCode":"advanced-plan-first","title":{"en":"Use what you have","zh":"先用已有食物"},"topicCodes":["planning","prevention-priority"],"sourceRefs":["vic-planning","ozharvest-2025","vic-storage"],"block":{"type":"paragraph","text":{"en":"Start before the shop. Look through the fridge, freezer and pantry, then choose ingredients that need using soon while still safe. A simple use-first area keeps them visible.","zh":"从购物前开始。查看冰箱、冷冻室和储物柜，优先考虑仍安全且需要尽快使用的食物。简单的优先使用区可以让它们更可见。"}}},{"chunkCode":"advanced-plan-first:1","entityCode":"advanced-plan-first","title":{"en":"Use what you have","zh":"先用已有食物"},"topicCodes":["planning","prevention-priority"],"sourceRefs":["vic-planning","ozharvest-2025","vic-storage"],"block":{"type":"paragraph","text":{"en":"Plan for the people who will actually eat. Link meals that share ingredients, and add only missing items to the list. A bulk bargain is not useful if it exceeds what you can use.","zh":"按实际就餐人数计划。安排能共用食材的餐食，只把缺少的物品加到清单。如果买得超过能使用的量，大包装优惠也未必有用。"}}},{"chunkCode":"advanced-plan-first:2","entityCode":"advanced-plan-first","title":{"en":"Use what you have","zh":"先用已有食物"},"topicCodes":["planning","prevention-priority"],"sourceRefs":["vic-planning","ozharvest-2025","vic-storage"],"block":{"type":"paragraph","text":{"en":"Example: you have carrots and half a tub of an ingredient. Plan a meal around them before choosing a recipe that requires a new shop. When plans change, review perishables again and make a safe storage plan.","zh":"例子：已有胡萝卜和半盒食材时，先围绕它们计划一餐，再考虑需要重新购物的菜谱。安排改变后，再查看易腐食物并制定安全储存计划。"}}},{"chunkCode":"advanced-plan-first:3","entityCode":"advanced-plan-first","title":{"en":"Use what you have","zh":"先用已有食物"},"topicCodes":["planning","prevention-priority"],"sourceRefs":["vic-planning","ozharvest-2025","vic-storage"],"block":{"type":"reflection","title":{"en":"Try it in your kitchen","zh":"在你的厨房试一试"},"text":{"en":"Plan one meal using what you already have. List only what is missing, and check portions.","zh":"用已有食物计划一餐，只列出缺少的物品，并核对份量。"}}},{"chunkCode":"advanced-storage:0","entityCode":"advanced-storage","title":{"en":"Store with care","zh":"合理储存"},"topicCodes":["storage-safety"],"sourceRefs":["fsanz-dates","fsanz-safety","vic-storage"],"block":{"type":"paragraph","text":{"en":"Use-by is a safety limit: do not eat food after that date. Best-before mainly concerns quality. It is not a promise that any food is safe regardless of storage or condition.","zh":"Use-by 是安全期限：过期后不要食用。Best-before 主要涉及品质，并不保证任何储存方式、任何状态下的食物都安全。"}}},{"chunkCode":"advanced-storage:1","entityCode":"advanced-storage","title":{"en":"Store with care","zh":"合理储存"},"topicCodes":["storage-safety"],"sourceRefs":["fsanz-dates","fsanz-safety","vic-storage"],"block":{"type":"paragraph","text":{"en":"Follow the product''s storage and preparation instructions. Keep perishable food refrigerated at 5°C or colder. Thaw frozen perishable food in the fridge or with a microwave rather than at room temperature.","zh":"遵循产品的储存和准备说明。易腐食物应冷藏在 5°C 或更低温度；冷冻易腐食物应在冰箱或用微波炉解冻，不采用室温解冻。"}}},{"chunkCode":"advanced-storage:2","entityCode":"advanced-storage","title":{"en":"Store with care","zh":"合理储存"},"topicCodes":["storage-safety"],"sourceRefs":["fsanz-dates","fsanz-safety","vic-storage"],"block":{"type":"paragraph","text":{"en":"Label and date freezer portions so they are identifiable. Visibility helps you remember food, but must not replace safe cold storage. Do not invent a longer use-by date or rely only on a normal smell.","zh":"标注冷冻份量的名称和日期，方便辨认。让食物可见有助于记得使用，但不能替代安全冷藏。不要自行延长 use-by 日期，也不要只凭气味正常作判断。"}}},{"chunkCode":"advanced-storage:3","entityCode":"advanced-storage","title":{"en":"Store with care","zh":"合理储存"},"topicCodes":["storage-safety"],"sourceRefs":["fsanz-dates","fsanz-safety","vic-storage"],"block":{"type":"reflection","title":{"en":"Try it in your kitchen","zh":"在你的厨房试一试"},"text":{"en":"Read one food label. Identify the date type and storage instructions, and decide a safe plan before the relevant limit.","zh":"阅读一个食品标签，辨认日期类型和储存要求，在相应期限前安排安全使用。"}}},{"chunkCode":"advanced-climate:0","entityCode":"advanced-climate","title":{"en":"Waste & climate action","zh":"浪费与气候行动"},"topicCodes":["climate-basics","climate-evidence"],"sourceRefs":["unfccc-2024","unep-index-2024","sdg13","vic-fogo"],"block":{"type":"paragraph","text":{"en":"Food uses land, water and energy before it is eaten. Preventing edible waste helps avoid wasting those inputs. Suitable organics collection handles unavoidable scraps; it cannot undo the resources already used.","zh":"食物在食用前就需要土地、水和能源。避免可食用食物浪费也关注这些投入。合适的有机物收集可以处理无法避免的残余，却不能撤销已经投入的资源。"}}},{"chunkCode":"advanced-climate:1","entityCode":"advanced-climate","title":{"en":"Waste & climate action","zh":"浪费与气候行动"},"topicCodes":["climate-basics","climate-evidence"],"sourceRefs":["unfccc-2024","unep-index-2024","sdg13","vic-fogo"],"block":{"type":"paragraph","text":{"en":"Read climate data with its scope. UNFCCC''s 2024 article links food loss and waste to 8–10% of annual global greenhouse gas emissions. This includes both loss and waste, globally; it is not a percentage saved by this learner.","zh":"阅读气候数据时保留范围。UNFCCC 2024 年文章将食物损失和浪费与全球年度温室气体排放的 8–10% 联系起来。它同时涵盖损失与浪费、范围为全球，并非本学习者节省的比例。"}}},{"chunkCode":"advanced-climate:2","entityCode":"advanced-climate","title":{"en":"Waste & climate action","zh":"浪费与气候行动"},"topicCodes":["climate-basics","climate-evidence"],"sourceRefs":["unfccc-2024","unep-index-2024","sdg13","vic-fogo"],"block":{"type":"paragraph","text":{"en":"SDG 13.3 includes climate education and awareness. These lessons and reflection support that educational direction. Quiz results measure learning performance, not national curriculum indicators or personal carbon savings.","zh":"SDG 13.3 包含气候教育与意识提升。课程和反思符合这一教育方向。测验成绩反映学习表现，不测量国家课程指标或个人减排量。"}}},{"chunkCode":"advanced-climate:3","entityCode":"advanced-climate","title":{"en":"Waste & climate action","zh":"浪费与气候行动"},"topicCodes":["climate-basics","climate-evidence"],"sourceRefs":["unfccc-2024","unep-index-2024","sdg13","vic-fogo"],"block":{"type":"reflection","title":{"en":"Try it in your kitchen","zh":"在你的厨房试一试"},"text":{"en":"Choose one prevention habit for this week. Describe the action you will take without claiming a measured emissions saving.","zh":"为本周选一个预防浪费的习惯，说明要做的行动，不把它写成已经测量的减排量。"}}},{"chunkCode":"waste-climate-sdg13:0","entityCode":"waste-climate-sdg13","title":{"en":"Less waste. More climate action.","zh":"减少浪费，参与气候行动。"},"topicCodes":["climate-basics","climate-evidence"],"sourceRefs":["unfccc-2024"],"block":{"type":"fact","value":{"en":"8–10%","zh":"8–10%"},"text":{"en":"of global greenhouse gas emissions are linked to food loss and waste.","zh":"全球温室气体排放与食物损失和浪费有关的比例。"},"scope":{"en":"Annual global emissions; food loss and food waste combined. Cited by UNFCCC on 30 September 2024.","zh":"全球年度排放；同时涵盖食物损失和食物浪费。UNFCCC 于 2024 年 9 月 30 日引用。"},"sourceRefs":["unfccc-2024"]}},{"chunkCode":"waste-climate-sdg13:1","entityCode":"waste-climate-sdg13","title":{"en":"Less waste. More climate action.","zh":"减少浪费，参与气候行动。"},"topicCodes":["climate-basics","climate-evidence"],"sourceRefs":["unfccc-2024","sdg13"],"block":{"type":"paragraph","text":{"en":"Producing food uses energy. Wasting it wastes those resources too.","zh":"生产食物需要能源。浪费食物，也浪费了这些资源。"}}},{"chunkCode":"waste-climate-sdg13:2","entityCode":"waste-climate-sdg13","title":{"en":"Less waste. More climate action.","zh":"减少浪费，参与气候行动。"},"topicCodes":["climate-basics","climate-evidence"],"sourceRefs":["sdg13"],"block":{"type":"sdg-callout","goal":13,"target":"13.3","assetKey":"sdg-13-climate-action","title":{"en":"SDG 13.3","zh":"SDG 13.3"},"text":{"en":"Learn. Understand. Take action.","zh":"学习、理解、行动。"},"detail":{"en":"Climate education and awareness.","zh":"气候教育与意识提升。"},"sourceRefs":["sdg13"],"attributionRequired":true}},{"chunkCode":"waste-climate-sdg13:3","entityCode":"waste-climate-sdg13","title":{"en":"Less waste. More climate action.","zh":"减少浪费，参与气候行动。"},"topicCodes":["climate-basics","climate-evidence"],"sourceRefs":["unfccc-2024","sdg13"],"block":{"type":"reflection","title":{"en":"One action this week","zh":"本周的一项行动"},"text":{"en":"Plan one meal using what you already have.","zh":"用家里已有的食物计划一餐。"}}},{"chunkCode":"global-food-waste-evidence:0","entityCode":"global-food-waste-evidence","title":{"en":"Read the food waste numbers","zh":"读懂食物浪费数据"},"topicCodes":[],"sourceRefs":["unep-index-2024"],"block":{"type":"fact","value":{"en":"1.05 billion tonnes","zh":"10.5 亿吨"},"text":{"en":"Estimated food waste at consumer levels in 2022.","zh":"2022 年消费端食物废弃物估计量。"},"scope":{"en":"Retail, food service and households, including inedible parts; report released in 2024.","zh":"涵盖零售、餐饮服务和家庭，并包含不可食用部分；报告于 2024 年发布。"},"sourceRefs":["unep-index-2024"]}},{"chunkCode":"global-food-waste-evidence:1","entityCode":"global-food-waste-evidence","title":{"en":"Read the food waste numbers","zh":"读懂食物浪费数据"},"topicCodes":[],"sourceRefs":["unep-index-2024"],"block":{"type":"paragraph","text":{"en":"The observation year is 2022. The report date is 2024. Neither makes the estimate a reading of your kitchen today.","zh":"统计年份是 2022 年，报告年份是 2024 年；它们都不能让这个数值变成对你今天厨房的测量。"}}},{"chunkCode":"global-food-waste-evidence:2","entityCode":"global-food-waste-evidence","title":{"en":"Read the food waste numbers","zh":"读懂食物浪费数据"},"topicCodes":[],"sourceRefs":["unep-index-2024"],"block":{"type":"reflection","title":{"en":"One action this week","zh":"本周的一项行动"},"text":{"en":"When sharing a number, include its year, unit and scope.","zh":"分享数据时，一起注明年份、单位和范围。"}}},{"chunkCode":"local-sorting-guide:0","entityCode":"local-sorting-guide","title":{"en":"Check your collection first","zh":"先核对收集服务"},"topicCodes":["sorting","clean-streams","local-collection"],"sourceRefs":["vic-sorting"],"block":{"type":"paragraph","text":{"en":"Find the service for your address. Councils and private providers can differ, including separate glass or food-organics services.","zh":"找到服务你住所的提供方。Council 与私人服务商可能不同，包括单独玻璃或厨余收集。"}}},{"chunkCode":"local-sorting-guide:1","entityCode":"local-sorting-guide","title":{"en":"Check your collection first","zh":"先核对收集服务"},"topicCodes":["sorting","clean-streams","local-collection"],"sourceRefs":["vic-sorting"],"block":{"type":"paragraph","text":{"en":"Do not infer a local rule from bin colour or a material symbol. If a route is unclear, check the specific item before putting it in recycling.","zh":"不要根据桶色或材料符号推断当地规则。处理方式不明时，先查具体物品再投回收。"}}},{"chunkCode":"local-sorting-guide:2","entityCode":"local-sorting-guide","title":{"en":"Check your collection first","zh":"先核对收集服务"},"topicCodes":["sorting","clean-streams","local-collection"],"sourceRefs":["vic-sorting"],"block":{"type":"reflection","title":{"en":"One action this week","zh":"本周的一项行动"},"text":{"en":"Look up one uncertain package using your current council or provider guide.","zh":"用当前 council 或服务商指引查询一件不确定的包装。"}}},{"chunkCode":"materials-and-components:0","entityCode":"materials-and-components","title":{"en":"Read every packaging part","zh":"阅读每个包装部件"},"topicCodes":["materials","components","reuse-resources"],"sourceRefs":["arl"],"block":{"type":"paragraph","text":{"en":"Match each component name to its label. A conditional instruction matters as much as the recycling symbol.","zh":"将每个部件名称与对应标签匹配。有条件说明与回收符号一样重要。"}}},{"chunkCode":"materials-and-components:1","entityCode":"materials-and-components","title":{"en":"Read every packaging part","zh":"阅读每个包装部件"},"topicCodes":["materials","components","reuse-resources"],"sourceRefs":["arl"],"block":{"type":"paragraph","text":{"en":"If you cannot confirm an item''s acceptance, check rather than adding an uncertain item to recycling.","zh":"不能确认是否接受时，应先查，不把不确定的物品加入回收。"}}},{"chunkCode":"materials-and-components:2","entityCode":"materials-and-components","title":{"en":"Read every packaging part","zh":"阅读每个包装部件"},"topicCodes":["materials","components","reuse-resources"],"sourceRefs":["arl"],"block":{"type":"reflection","title":{"en":"One action this week","zh":"本周的一项行动"},"text":{"en":"Find the instruction for both the container and its lid.","zh":"找出容器和盖子分别对应的说明。"}}},{"chunkCode":"plan-before-shopping:0","entityCode":"plan-before-shopping","title":{"en":"Build a use-first meal","zh":"计划优先使用的一餐"},"topicCodes":["causes","planning","prevention-priority"],"sourceRefs":["vic-planning"],"block":{"type":"paragraph","text":{"en":"Check fridge, freezer and pantry. Make a visible use-first area for food that needs attention while still safe.","zh":"查看冰箱、冷冻室和储物柜。为仍安全、需要优先使用的食物安排可见区域。"}}},{"chunkCode":"plan-before-shopping:1","entityCode":"plan-before-shopping","title":{"en":"Build a use-first meal","zh":"计划优先使用的一餐"},"topicCodes":["causes","planning","prevention-priority"],"sourceRefs":["vic-planning"],"block":{"type":"paragraph","text":{"en":"Choose portions for the people who will eat, and meals that can share ingredients. Update the plan when your week changes.","zh":"按实际人数安排份量，并选择能共用食材的餐食。每周安排变化时更新计划。"}}},{"chunkCode":"plan-before-shopping:2","entityCode":"plan-before-shopping","title":{"en":"Build a use-first meal","zh":"计划优先使用的一餐"},"topicCodes":["causes","planning","prevention-priority"],"sourceRefs":["vic-planning"],"block":{"type":"reflection","title":{"en":"One action this week","zh":"本周的一项行动"},"text":{"en":"Write a short shopping list from one meal built around existing food.","zh":"从一餐以已有食物为主的计划，写出简短购物清单。"}}},{"chunkCode":"date-labels-and-storage:0","entityCode":"date-labels-and-storage","title":{"en":"Safety first, waste less","zh":"安全优先，减少浪费"},"topicCodes":["storage-safety"],"sourceRefs":["fsanz-dates"],"block":{"type":"paragraph","text":{"en":"Do not eat food past its use-by date. Best-before mainly concerns quality, while condition and storage remain relevant.","zh":"不要食用超过 use-by 日期的食物。Best-before 主要涉及品质，食物状态与储存条件仍需考虑。"}}},{"chunkCode":"date-labels-and-storage:1","entityCode":"date-labels-and-storage","title":{"en":"Safety first, waste less","zh":"安全优先，减少浪费"},"topicCodes":["storage-safety"],"sourceRefs":["fsanz-dates"],"block":{"type":"paragraph","text":{"en":"Follow the label''s storage and preparation directions. A date alone cannot account for inappropriate storage.","zh":"遵循标签的储存和准备说明，日期本身不能弥补不当储存。"}}},{"chunkCode":"date-labels-and-storage:2","entityCode":"date-labels-and-storage","title":{"en":"Safety first, waste less","zh":"安全优先，减少浪费"},"topicCodes":["storage-safety"],"sourceRefs":["fsanz-dates"],"block":{"type":"reflection","title":{"en":"One action this week","zh":"本周的一项行动"},"text":{"en":"Check a label''s date type and storage directions before making a use-first plan.","zh":"安排优先使用计划前，查看标签的日期类型与储存要求。"}}},{"chunkCode":"news-zero-waste-2026:0","entityCode":"news-zero-waste-2026","title":{"en":"Zero Waste Day puts food waste in focus","zh":"零废弃日聚焦食物浪费"},"topicCodes":[],"sourceRefs":["unep-zero-waste-2026"],"block":{"type":"paragraph","text":{"en":"The announcement discusses food waste across homes, businesses and cities. It highlights awareness and practical prevention as part of wider environmental action.","zh":"公告讨论了家庭、企业与城市层面的食物浪费，强调意识提升与实际预防在环境行动中的作用。"}}},{"chunkCode":"news-zero-waste-2026:1","entityCode":"news-zero-waste-2026","title":{"en":"Zero Waste Day puts food waste in focus","zh":"零废弃日聚焦食物浪费"},"topicCodes":[],"sourceRefs":["unep-zero-waste-2026"],"block":{"type":"reflection","title":{"en":"One action this week","zh":"本周的一项行动"},"text":{"en":"Choose a prevention habit to discuss with someone at home.","zh":"选择一个预防浪费的习惯，与家里的人交流。"}}},{"chunkCode":"news-cds-vic-2026:0","entityCode":"news-cds-vic-2026","title":{"en":"Victoria reports a container-return milestone","zh":"Victoria 公布容器回收里程碑"},"topicCodes":[],"sourceRefs":["vic-cds-news-2026","cds-vic"],"block":{"type":"paragraph","text":{"en":"This is a government-reported cumulative milestone at the publication date. It is not this app''s return count or a live total.","zh":"这是政府在发布日期报告的累计里程碑，并非本 App 的回收计数或实时总量。"}}},{"chunkCode":"news-cds-vic-2026:1","entityCode":"news-cds-vic-2026","title":{"en":"Victoria reports a container-return milestone","zh":"Victoria 公布容器回收里程碑"},"topicCodes":[],"sourceRefs":["vic-cds-news-2026","cds-vic"],"block":{"type":"paragraph","text":{"en":"For a return you plan today, use CDS Vic''s current eligibility and refund-point information.","zh":"如果计划今天退回容器，请查看 CDS Vic 当前的资格与退费点信息。"}}},{"chunkCode":"news-cds-vic-2026:2","entityCode":"news-cds-vic-2026","title":{"en":"Victoria reports a container-return milestone","zh":"Victoria 公布容器回收里程碑"},"topicCodes":[],"sourceRefs":["vic-cds-news-2026","cds-vic"],"block":{"type":"reflection","title":{"en":"One action this week","zh":"本周的一项行动"},"text":{"en":"Check whether one drink container is eligible before planning a return.","zh":"计划退回前，核对一个饮料容器是否符合条件。"}}},{"chunkCode":"news-date-labels-2024:0","entityCode":"news-date-labels-2024","title":{"en":"Why food date labels cause confusion","zh":"食品日期标签为何容易混淆"},"topicCodes":[],"sourceRefs":["fsanz-date-news-2024","fsanz-dates"],"block":{"type":"paragraph","text":{"en":"The article distinguishes use-by from best-before. Read current FSANZ guidance and product storage instructions when deciding how to handle food.","zh":"文章区分 use-by 和 best-before。处理食物时应结合 FSANZ 当前指引与产品储存说明。"}}},{"chunkCode":"news-date-labels-2024:1","entityCode":"news-date-labels-2024","title":{"en":"Why food date labels cause confusion","zh":"食品日期标签为何容易混淆"},"topicCodes":[],"sourceRefs":["fsanz-date-news-2024","fsanz-dates"],"block":{"type":"reflection","title":{"en":"One action this week","zh":"本周的一项行动"},"text":{"en":"Explain the two date types in your own words, without saying smell overrides use-by.","zh":"用自己的话解释两类日期，但不要说气味可以推翻 use-by。"}}},{"chunkCode":"intermediate-components:reuse-bridge-v2","entityCode":"intermediate-components","title":{"en":"Reuse suitable items","zh":"再利用合适物品"},"topicCodes":["reuse-resources"],"sourceRefs":["vic-reuse","vic-single-use"],"block":{"type":"paragraph","text":{"en":"Reuse suitable items: keep an existing item in use instead of replacing it after one use. Making products uses materials, energy and water. A reusable cup, water bottle or shopping bag can replace repeated disposable purchases. Check that the item is suitable, clean it and follow its care instructions. Do not repurpose packaging in ways that could create food or chemical safety risks. Recycling also needs collection and processing, so consider safe reuse first. This is general Victoria guidance, not a promise about a particular council or business.","zh":"再利用合适物品：让已有物品继续使用，避免用一次就换新。制造产品需要材料、能源和水。可重复使用的杯子、水瓶或购物袋可以代替反复购买的一次性物品。核对物品是否适用，清洁并遵循护理说明。不要把包装改作可能造成食品或化学安全风险的用途。回收也需要收集与处理，因此先考虑安全再利用。这是维州的一般指引，不保证某个 council 或商家提供具体服务。"}}}],"practiceTemplates":[{"templateCode":"tutor-materials-v1","topicCode":"materials","title":{"en":"Identify the material","zh":"辨认材料"},"prompt":{"en":"An unlabelled shiny wrapper is found. What should you check first?","zh":"找到一张没有标签的闪亮包装，应先检查什么？"},"sourceRefs":["vic-sorting","arl"],"options":[{"optionId":"a","text":{"en":"Its confirmed material","zh":"它已确认的材质"}},{"optionId":"b","text":{"en":"Its colour alone","zh":"只看颜色"}}],"correctOptionId":"a","explanation":{"en":"Its confirmed material. Check the cited teaching source for its scope.","zh":"它已确认的材质。请查看教学来源的适用范围。"},"independentStatus":"pending"},{"templateCode":"tutor-sorting-v1","topicCode":"sorting","title":{"en":"Check collection conditions","zh":"核对收集条件"},"prompt":{"en":"An organics service accepts food scraps but no packaging. How do you prepare a fruit peel with a sticker?","zh":"有机物服务接收食物残余但不接收包装，带贴纸的果皮如何准备？"},"sourceRefs":["vic-sorting","vic-fogo"],"options":[{"optionId":"b","text":{"en":"Leave the sticker because it is small","zh":"贴纸很小，可以保留"}},{"optionId":"a","text":{"en":"Remove the sticker and check the service instructions","zh":"去掉贴纸并核对服务说明"}}],"correctOptionId":"a","explanation":{"en":"Remove the sticker and check the service instructions. Check the cited teaching source for its scope.","zh":"去掉贴纸并核对服务说明。请查看教学来源的适用范围。"},"independentStatus":"pending"},{"templateCode":"tutor-causes-v1","topicCode":"causes","title":{"en":"Notice avoidable waste","zh":"发现可避免的浪费"},"prompt":{"en":"You forgot some usable vegetables behind newer shopping. What habit helps?","zh":"可用蔬菜被新买的东西挡住，什么习惯有帮助？"},"sourceRefs":["vic-planning"],"options":[{"optionId":"a","text":{"en":"Check what is already available before shopping","zh":"购物前查看已有食物"}},{"optionId":"b","text":{"en":"Buy extra vegetables without checking","zh":"不查看，再多买蔬菜"}}],"correctOptionId":"a","explanation":{"en":"Check what is already available before shopping. Check the cited teaching source for its scope.","zh":"购物前查看已有食物。请查看教学来源的适用范围。"},"independentStatus":"pending"},{"templateCode":"tutor-climate-basics-v1","topicCode":"climate-basics","title":{"en":"Connect waste and climate","zh":"联系浪费与气候"},"prompt":{"en":"Why can avoiding food waste help with climate action?","zh":"为什么避免食物浪费有助于气候行动？"},"sourceRefs":["unfccc-2024","sdg13"],"options":[{"optionId":"b","text":{"en":"Only the bin has an environmental impact","zh":"只有垃圾桶有环境影响"}},{"optionId":"a","text":{"en":"Food production and supply have already used resources","zh":"食物生产和供应已投入资源"}}],"correctOptionId":"a","explanation":{"en":"Food production and supply have already used resources. Check the cited teaching source for its scope.","zh":"食物生产和供应已投入资源。请查看教学来源的适用范围。"},"independentStatus":"pending"},{"templateCode":"tutor-components-v1","topicCode":"components","title":{"en":"Read each part","zh":"逐个阅读部件"},"prompt":{"en":"A sleeve and inner film have separate disposal instructions. What do you read?","zh":"纸套与内膜有不同处理说明，应阅读什么？"},"sourceRefs":["arl"],"options":[{"optionId":"a","text":{"en":"Each component and its own instruction","zh":"每个部件及各自说明"}},{"optionId":"b","text":{"en":"Only the sleeve instruction for both parts","zh":"只用纸套说明处理两个部件"}}],"correctOptionId":"a","explanation":{"en":"Each component and its own instruction. Check the cited teaching source for its scope.","zh":"每个部件及各自说明。请查看教学来源的适用范围。"},"independentStatus":"pending"},{"templateCode":"tutor-clean-streams-v1","topicCode":"clean-streams","title":{"en":"Prepare accepted recycling","zh":"准备可接收回收物"},"prompt":{"en":"Your service asks for loose, empty containers. What preparation fits?","zh":"当地服务要求容器倒空散放，怎样准备合适？"},"sourceRefs":["vic-sorting"],"options":[{"optionId":"b","text":{"en":"Bag containers with leftover food inside","zh":"容器装袋且保留食物残余"}},{"optionId":"a","text":{"en":"Empty accepted containers and keep them loose","zh":"倒空可接收容器并散放"}}],"correctOptionId":"a","explanation":{"en":"Empty accepted containers and keep them loose. Check the cited teaching source for its scope.","zh":"倒空可接收容器并散放。请查看教学来源的适用范围。"},"independentStatus":"pending"},{"templateCode":"tutor-local-collection-v1","topicCode":"local-collection","title":{"en":"Ask about the local route","zh":"询问当地方式"},"prompt":{"en":"A friend uses a separate glass collection. What should you check at your home?","zh":"朋友使用独立玻璃收集服务，在自己家应核对什么？"},"sourceRefs":["vic-sorting","vic-glass"],"options":[{"optionId":"a","text":{"en":"Your council collection rules","zh":"自己 council 的收集规则"}},{"optionId":"b","text":{"en":"Assume your friend’s service applies everywhere","zh":"认为朋友的服务处处适用"}}],"correctOptionId":"a","explanation":{"en":"Your council collection rules. Check the cited teaching source for its scope.","zh":"自己 council 的收集规则。请查看教学来源的适用范围。"},"independentStatus":"pending"},{"templateCode":"tutor-reuse-resources-v1","topicCode":"reuse-resources","title":{"en":"Reuse suitable items","zh":"再利用合适物品"},"prompt":{"en":"You have a clean, food-suitable lunch box. How can it reduce single-use packaging?","zh":"已有干净且适合食品的饭盒，如何减少一次性包装？"},"sourceRefs":["vic-reuse","vic-single-use"],"options":[{"optionId":"b","text":{"en":"Buy new disposable packaging every day","zh":"每天买新的即用即弃包装"}},{"optionId":"a","text":{"en":"Use it repeatedly where suitable","zh":"在适用时反复使用"}}],"correctOptionId":"a","explanation":{"en":"Use it repeatedly where suitable. Check the cited teaching source for its scope.","zh":"在适用时反复使用。请查看教学来源的适用范围。"},"independentStatus":"pending"},{"templateCode":"tutor-planning-v1","topicCode":"planning","title":{"en":"Plan with available food","zh":"用已有食物规划"},"prompt":{"en":"Before making your shopping list, what information helps avoid duplicates?","zh":"列购物清单前，什么信息有助于避免重复购买？"},"sourceRefs":["vic-planning"],"options":[{"optionId":"a","text":{"en":"What food is already available and usable","zh":"已有且可使用的食物"}},{"optionId":"b","text":{"en":"Only the latest advertisements","zh":"只看最新广告"}}],"correctOptionId":"a","explanation":{"en":"What food is already available and usable. Check the cited teaching source for its scope.","zh":"已有且可使用的食物。请查看教学来源的适用范围。"},"independentStatus":"pending"},{"templateCode":"tutor-storage-safety-v1","topicCode":"storage-safety","title":{"en":"Put safety first","zh":"安全优先"},"prompt":{"en":"A food is past its use-by date. Does a waste reduction goal make eating it safe?","zh":"食物已超过 use-by，减废目标会让食用变安全吗？"},"sourceRefs":["fsanz-dates","fsanz-safety"],"options":[{"optionId":"b","text":{"en":"Yes, if it smells pleasant","zh":"会，只要气味正常"}},{"optionId":"a","text":{"en":"No. Do not eat it; follow food safety advice","zh":"不会。不要食用，遵循食品安全指引"}}],"correctOptionId":"a","explanation":{"en":"No. Do not eat it; follow food safety advice. Check the cited teaching source for its scope.","zh":"不会。不要食用，遵循食品安全指引。请查看教学来源的适用范围。"},"independentStatus":"pending"},{"templateCode":"tutor-prevention-priority-v1","topicCode":"prevention-priority","title":{"en":"Prevent surplus first","zh":"先预防多余食物"},"prompt":{"en":"What prevents edible food waste before scraps need collection?","zh":"残余需要收集前，什么能预防可食用食物浪费？"},"sourceRefs":["vic-planning","vic-fogo"],"options":[{"optionId":"a","text":{"en":"Plan portions and use food safely","zh":"规划份量并安全使用食物"}},{"optionId":"b","text":{"en":"Buy more because composting is available","zh":"因为有堆肥服务而多买"}}],"correctOptionId":"a","explanation":{"en":"Plan portions and use food safely. Check the cited teaching source for its scope.","zh":"规划份量并安全使用食物。请查看教学来源的适用范围。"},"independentStatus":"pending"},{"templateCode":"tutor-climate-evidence-v1","topicCode":"climate-evidence","title":{"en":"Read dates and scope","zh":"阅读年份与范围"},"prompt":{"en":"A 2024 report describes a 2022 estimate. Which date describes the observation?","zh":"2024 年报告描述 2022 年估计，哪个年份是统计时期？"},"sourceRefs":["unep-index-2024","sdg13"],"options":[{"optionId":"b","text":{"en":"The current year whenever you open the app","zh":"每次打开 App 的当前年份"}},{"optionId":"a","text":{"en":"2022, while 2024 is the publication year","zh":"2022 年，2024 年是发布年"}}],"correctOptionId":"a","explanation":{"en":"2022, while 2024 is the publication year. Check the cited teaching source for its scope.","zh":"2022 年，2024 年是发布年。请查看教学来源的适用范围。"},"independentStatus":"pending"}],"quickPrompts":[{"en":"Explain simply","zh":"简单解释"},{"en":"Give an everyday example","zh":"举个生活例子"},{"en":"How does this relate to SDG 13.3?","zh":"这与 SDG 13.3 有何关系？"}]}'::jsonb,'{"status":"pending","author":"NarIyirm","reviewer":null,"reviewedAt":null,"approvedManifestHash":null}'::jsonb);
